cssRules:
.hero-banner {
  padding: 32px 24px;
  background: radial-gradient(circle at top left, rgba(59, 130, 246, 0.08), transparent 70%);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  margin-bottom: 24px;
}
.badge {
  display: inline-block;
  font-size: 11px;
  font-family: monospace;
  color: #60a5fa;
  background: rgba(59, 130, 246, 0.12);
  padding: 2px 8px;
  border-radius: 4px;
  margin-bottom: 12px;
}
.headline {
  font-size: 24px;
  font-weight: 700;
  color: #f8fafc;
  letter-spacing: -0.02em;
  margin: 0 0 8px 0;
}
.lead {
  font-size: 13px;
  color: #94a3b8;
  margin: 0;
  max-width: 600px;
}
